mapper.insert:

    SELECT SEQ_CAMPAIGN_NO.NEXTVAL FROM DUAL

INSERT 
  INTO 
       CL_CAMPAIGN 
       (
       CAMPAIGN_NO
     , CAMPAIGN_TITLE
     , CAMPAIGN_CONTENT
     , START_DATE
     , END_DATE
     , MEMBER_NO
     , CATEGORY_NO
     , STATUS
	   ) 
VALUES 
	   (
       #{campaignNo}
     , #{campaignTitle}
     , #{campaignContent}
     , #{startDate}
     , #{endDate}
     , #{memberNo}
     , #{categoryNo}
     , #{status}
	   )

        INSERT 
		  INTO 
		       CL_CAMPAIGN_ATTACHMENT 
			   (
			   FILE_NO
          	 , REF_BNO
          	 , ORIGIN_NAME
          	 , CHANGE_NAME
          	 , FILE_LEVEL
          	 , FILE_PATH
          	 , UPLOAD_DATE
        	   ) 
	   VALUES 
	          (
			  SEQ_CAMPAIGN_FILE_NO.NEXTVAL
          	, #{refBno}
          	, #{originName}
          	, #{changeName}
          	, #{fileLevel}
          	, #{filePath}
          	, SYSDATE
        	  )
